def migrate_existing_kits(apps, schema_editor):
    """Older kits: the whole price was deductible, nothing refundable; 'converted' no longer exists."""
    TrialKitOrder = apps.get_model("trialkit", "TrialKitOrder")
    for kit in TrialKitOrder.objects.all():
        kit.credit_amount = kit.price
        if kit.fulfillment == "converted":
            kit.fulfillment = "returned"
        kit.save(update_fields=["credit_amount", "fulfillment"])


Migration.operations.append(migrations.RunPython(migrate_existing_kits, migrations.RunPython.noop))
